BEGIN;

-- ユウが実際に解いたときに残したメモ（user_question_progress.memo）を手がかりに、
-- 具体的に「わからなかった」6問(q19/q26/q43/q44/q56/q88)の解説を、その疑問に
-- ピンポイントで答える形に書き直す（非破壊マージ。既存キーは上書き、新規キーは追加）。
UPDATE public.questions q
SET explanation_data = q.explanation_data || v.value
FROM jsonb_each('{"python-drill-q19": {"point": "map(関数, 一覧)は「渡した関数」を各要素に当てはめた結果を、filter(関数, 一覧)は「渡した関数」がTrueを返した要素だけを返す。", "kid": "map(lambda x: x * x, nums)の1つ目の引数lambda x: x * xは「xを受け取ってx*xを返す関数」。これをnumsの要素1つ1つに当てはめるので[1,4,9,16,25]ができる。filter(lambda x: x % 2 == 0, nums)の1つ目の引数は「xが偶数ならTrue」を返す関数。これをnumsの各要素に当てて、Trueが返った要素([2,4])だけ残す。", "terms": [["map(関数, 一覧)", "一覧の要素それぞれに関数を当てはめた結果を順に返す。第一引数は「適用したい関数そのもの」（lambdaでも普通のdefで作った関数でもよい）"], ["filter(関数, 一覧)", "一覧の要素のうち、関数に渡してTrueが返ってきた要素だけを残す"], ["lambda x: 式", "名前を付けずにその場で作る小さな関数（無名関数）。xを受け取って式の結果を返す"]], "think": "map()とfilter()はどちらも「第一引数に関数、第二引数に一覧」を渡す形。map(lambda x: x * x, nums)は、lambda x: x * x（xを受け取ってx*xを返す関数）をnumsの各要素に順番に適用し、[1,4,9,16,25]を作る。filter(lambda x: x % 2 == 0, nums)は、lambda x: x % 2 == 0（xが偶数かどうかを判定する関数）をnumsの各要素に当てて、Trueだった要素だけを残すので[2,4]になる。", "vs": "map/filterが返すのはイテレータそのものであり、リストではない。list(map(...))のようにlist()で包んで初めて中身の並びが見える形になる点を混同しやすい。第一引数を「関数」だと意識せず記号のように読み飛ばすと、map(関数, 一覧)とfilter(関数, 一覧)で「何をしているか」が同じに見えてしまうので注意。"}, "python-drill-q26": {"point": "[y for x in data if (y := x * 2) > 6]は「(y := x * 2)でyにx*2を代入しつつ、その場でy > 6かどうかも判定する」という2つの仕事を1行でこなしている。", "kid": "dataの要素を1つずつxに取り出し、まずy := x * 2でy(=xの2倍)を計算する。次にそのyが6より大きいかどうかをその場で判定し、6より大きければyをresultに入れる。yを計算するのと判定するのを同時に済ませているのが:=の役割。", "calc": "1つずつ順番に確かめる。\n\nx=1 → y = 1*2 = 2 → 2 > 6 ? いいえ → 除外\nx=2 → y = 2*2 = 4 → 4 > 6 ? いいえ → 除外\nx=3 → y = 3*2 = 6 → 6 > 6 ? いいえ（同じ数は「より大きい」に含まれない）→ 除外\nx=4 → y = 4*2 = 8 → 8 > 6 ? はい → 採用\nx=5 → y = 5*2 = 10 → 10 > 6 ? はい → 採用\nx=6 → y = 6*2 = 12 → 12 > 6 ? はい → 採用\n\n採用されたyを順番に並べると: [8, 10, 12]", "think": "内包表記[y for x in data if 条件]は「dataの各xについて、条件がTrueならyをresultに入れる」という形。今回の条件部分(y := x * 2) > 6は、①x * 2を計算してyという変数に代入する、②そのyが6より大きいかを判定する、という2つの処理を1つの式でやっている。x=1,2,3のときはy=2,4,6でどれも6より大きくないので除外され、x=4,5,6のときはy=8,10,12でどれも6より大きいのでresultに採用される。だから最終的にresultは[8, 10, 12]になる。", "vs": "通常の=は文であり式の中には書けないが、:=は式なので条件式の中にも書ける。もしy = x * 2と書いて別の行でif y > 6とした場合と最終的な計算結果は同じだが、内包表記の1行の中では通常の=は使えず、:=でなければ書けない、という構文上の制約が背景にある。"}, "python-drill-q43": {"point": "with Resource():の実行順序は「①インスタンス生成→②__enter__が呼ばれる（openが出る）→③withブロックの中身（usingが出る）→④__exit__が呼ばれる（closeが出る）」の順。", "kid": "with Resource():と書くと、まずResource()でインスタンスが作られ、続けて自動的に__enter__()が呼ばれてprint(\"open\")が実行される。そのあとwithブロックの中身print(\"using\")が実行され、ブロックを抜けるときに自動的に__exit__()が呼ばれてprint(\"close\")が実行される。", "think": "with Resource():という行が実行されると、まずResource()でインスタンスが1つ作られる。次にPythonが自動的にそのインスタンスの__enter__()メソッドを呼ぶ。__enter__の中身はprint(\"open\")なので、ここで真っ先に\"open\"が出力される。__enter__の最後にあるreturn selfは、with Resource() as r:のようにasを使ったときにrへ代入される値を指定するためのもの。今回のコードにはasが無いので、return selfの戻り値はどこにも受け取られず捨てられるが、その前のprint(\"open\")はreturn selfの有無に関係なくすでに実行済みなので、出力には影響しない。__enter__が終わると、withブロックの中身print(\"using\")が実行され\"using\"が出力される。ブロックを抜けるタイミングで自動的に__exit__()が呼ばれ、print(\"close\")で\"close\"が出力される。よって出力順は\"open\"→\"using\"→\"close\"。", "vs": "「withブロックの中身(using)が先に実行されて、その前後をopen/closeで挟む」という直感は半分正しいが、実際に一番最初に動くのは__enter__（open）であり、withブロックの中身（using）はその後。__enter__が終わってからブロックの中身が実行される、という順番を取り違えやすい。またreturn selfは「asで受け取る値」を決めるだけで、__enter__の実行タイミングやopenが出力されるタイミングには関係しない。"}, "python-drill-q44": {"usecase": "「関数を返す関数」（クロージャ／ファクトリ関数）は実務でもよく使う型。たとえば『割引率だけ違う複数の計算関数を作りたい』『ボタンごとにIDだけ違うクリックハンドラを作りたい』『接頭辞だけ違うログ出力関数を作りたい』のように、ロジックは同じだけど固定したいパラメータだけ違う関数をいくつも作りたい場面で使われる。内側と外側の関数をわざわざ分けているのは、外側の関数を1回呼ぶごとに「そのfactorを覚えたまま動く専用の関数」を1つ作るため。1つの関数にまとめてしまうと、factorを固定して持ち運ぶ入れ物（クロージャ）自体が作れなくなる。"}, "python-drill-q56": {"usecase": "実務での使い分けの目安: ①データが大きい、または結果を1回しか使わないなら generator（必要な分だけ計算するのでメモリを節約できる）。例: 巨大なログファイルを1行ずつ読んで処理する場合。②同じ結果を何度も見返したい、要素数を数えたい、添字でアクセスしたいなら list（generatorは1回使い切ると空になり、添字アクセスもできない）。迷ったら、まずlistで書いてみて、メモリや速度が問題になってからgeneratorに切り替える、という順序でも実務上は十分。"}, "python-drill-q88": {"point": "greet.__name__の丸括弧()は無いので関数は呼び出されない。これは「greetという名前の中身が持っている、自分自身の名前」という属性を読みに行くだけの操作。", "kid": "greet.__name__は関数を実行しているのではなく（丸括弧()が無いので実行はされない）、greetという名前の中身（オブジェクト）が持つ「自分の名前」という属性を読み取っているだけ。@loggerのせいでgreetという名前の中身は実際にはwrapper関数にすり替わっているので、「自分の名前」を聞くとwrapperという答えが返ってくる。", "terms": [["__name__", "関数オブジェクトが自分自身に持っている「名前」の属性（文字列）。greet.__name__のように丸括弧を付けずに読み取る、関数を呼び出す操作ではない"], ["functools.wraps", "デコレータの中でwrapper関数に元の関数の__name__などの情報をコピーするための道具"]], "vs": "greet()（丸括弧あり・関数を実行して戻り値を得る）とgreet.__name__（丸括弧なし・関数オブジェクトが持つ属性を読むだけ）は全くの別操作。functools.wraps(func)を使っていれば元の名前情報がコピーされてgreet.__name__は''greet''に戻るが、このコードには無いので、実体であるwrapperの名前がそのまま出る。"}}'::jsonb) AS v(key, value)
WHERE q.source_ref = v.key
  AND q.subject_id = (SELECT id FROM public.subjects WHERE slug = 'python-drill')
  AND q.explanation_data IS NOT NULL;

COMMIT;
